    /Button
      Button.tsx
      Button.types.ts
      Button.css
      Button.stories.tsx
      Button.test.tsx
    /Card
      Card.tsx
      Card.types.ts
      Card.stories.tsx
      Card.test.tsx
  /styles
    _variables.css
    _mixins.css
  /utils
    /theme
      theme.ts
```

**Usage Example (Next.js):**
```tsx
import Button from '@/components/Button';

export default function HomePage() {
  return (
    <main>
      <Button variant="primary" size="large" onClick={() => alert('Clicked!')}>
        Get Started
      </Button>
      <Button variant="secondary">Learn More</Button>
    </main>
  );
}
```

